export function mountDurian({root,language,esc,sources}){
 const t=words[language],state={situation:null,soil:'unknown',health:'unknown',bearing:'unknown',nitrogen:'unknown',neighbours:'unknown',flush:'unknown',dropStage:'fruit'};
 const getSaved=()=>{try{return JSON.parse(localStorage.getItem('cn-durian-action-v2')||'null');}catch{return null;}};
 let saved=getSaved(),exampleMode=false;if(saved?.answers)Object.assign(state,saved.answers);try{const draft=JSON.parse(localStorage.getItem('cn-durian-draft-v2')||'null');if(draft)Object.assign(state,draft);}catch{}
 const saveDraft=()=>{try{localStorage.setItem('cn-durian-draft-v2',JSON.stringify(state));}catch{}};
 function fields(){
  const ids=['soil','health'];if(['flush','mature'].includes(state.situation))ids.push('bearing');
  if(state.situation==='flush')ids.push('nitrogen');if(state.situation==='mature')ids.push('flush','neighbours');
  if(['fruit','drop'].includes(state.situation))ids.push('flush');if(state.situation==='drop')ids.push('dropStage');
  return ids.map(id=>{let values,labels;if(id==='soil'){values=['unknown','dry','moist','wet'];labels=t.soil;}else if(id==='health'){values=['ok','poor','unknown'];labels=t.health;}else if(id==='dropStage'){values=['flowers','fruit'];labels=t.drop;}else{values=['unknown','yes','no'];labels=t.yn;}return `<label>${t.q[id]}<select data-durian-answer="${id}">${values.map((v,i)=>`<option value="${v}" ${state[id]===v?'selected':''}>${labels[i]}</option>`).join('')}</select></label>`;}).join('');
 }
 function render(){root.innerHTML=`<h1>${t.title}</h1><p>${t.intro}</p>${saved?`<p class="hint">${t.history} · ${new Date(saved.at).toLocaleDateString(language==='zh'?'zh-CN':language==='ms'?'ms-MY':'en')} <button type="button" class="plain" data-resume-action>${t.reset}</button></p>`:''}<div class="situation-tiles">${t.keys.map((k,i)=>`<button type="button" data-situation="${k}" aria-pressed="${state.situation===k}">${t.situations[i]}</button>`).join('')}</div>${state.situation?`<form class="durian-form"><div class="guide-fields">${fields()}</div><button class="primary" type="submit">${t.run}</button></form>`:''}<div class="durian-result" aria-live="polite"></div><details class="example-drawer"><summary>${t.example}</summary><div class="preset-row">${t.examples.map((v,i)=>`<button type="button" class="secondary" data-durian-example="${i}">${v}</button>`).join('')}</div></details>`;
  if(state.situation)root.querySelector('.durian-form').onsubmit=e=>{e.preventDefault();result();};
 }
 function result(){const key=decideDurian(state),[title,steps,review,cn]=durianCases[key][language];const target=root.querySelector('.durian-result');
 const same=saved&&JSON.stringify(saved.answers)===JSON.stringify(state),checked=same?saved.checked||[]:[];
 target.innerHTML=`<article class="card farmer-result">${exampleMode?`<p class="example-banner">${language==='zh'?'教学例子：请换成你自己树的情况后再使用。':language==='ms'?'Contoh: tukar kepada keadaan pokok sendiri sebelum digunakan.':'Example: replace these answers with your own tree’s situation before use.'}</p>`:''}<span class="pill">${t.priority}</span><h2>${title}</h2><h3>${t.today}</h3><div class="farmer-actions">${steps.split('|').map((step,i)=>`<label><input type="checkbox" data-task="${i}" ${checked.includes(i)?'checked':''}><span>${esc(step)}</span></label>`).join('')}</div><div class="next-check"><h3>${t.review}</h3><p>${review}</p>${durianNext(state).length?`<p class="hint">${language==='zh'?'只有观察到以下情况，才选择下一阶段；没有变化就继续当前行动。':language==='ms'?'Pilih hanya apabila keadaan ini benar-benar berlaku; jika tiada perubahan, teruskan pelan semasa.':'Choose only when one of these changes has actually occurred; otherwise continue the current plan.'}</p><div class="stage-transitions">${durianNext(state).map((n,i)=>`<button type="button" class="secondary" data-next-stage="${i}">${transitionLabels[language][n.id]} →</button>`).join('')}</div>`:''}</div><div class="cn-meaning"><h3>${t.cn}</h3><p>${cn}</p></div><button type="button" class="secondary" data-save-action ${exampleMode?'hidden':''}>${t.journal}</button><span class="durian-save-status" role="status"></span><p class="hint">${t.saved}</p><details><summary>${t.details}</summary><p>${t.limit}</p><p>${t.note}</p>${['P1','F2','E1','F1'].map(id=>sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<article class="source"><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><p class="hint">${esc(s.scope)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${t.source} ↗</a></article>`).join('')}</details></article>`;
 const calcWords={zh:['算清这次实际施了多少氮（可选）','产品用量（kg / 棵 / 本次）','包装含氮 N（%）：例如 15-15-15 的第一个 15','填入实际用量与包装含氮百分比。','这是投入氮量，不是树体含氮量、C:N 或推荐用量。','本次投入氮：','输入有效的非负用量及 0–100% 的氮含量。'],en:['Work out the nitrogen applied (optional)','Product used (kg / tree / this application)','Label N (%): the first 15 in 15-15-15','Enter the actual amount and label nitrogen percentage.','This is nitrogen input, not tissue nitrogen, C:N or a recommended dose.','Nitrogen applied: ','Enter a valid nonnegative amount and 0–100% N.'],ms:['Kira nitrogen yang digunakan (pilihan)','Produk digunakan (kg / pokok / penggunaan ini)','N pada label (%): 15 pertama dalam 15-15-15','Isi kuantiti sebenar dan peratus nitrogen label.','Ini input nitrogen, bukan nitrogen tisu, C:N atau kadar disyorkan.','Nitrogen digunakan: ','Isi kuantiti bukan negatif dan 0–100% N.']}[language];
 const calc=document.createElement('details');calc.className='nitrogen-worksheet';calc.innerHTML=`<summary>${calcWords[0]}</summary><div class="guide-fields"><label>${calcWords[1]}<input data-n-kg type="number" inputmode="decimal" min="0" step="any"></label><label>${calcWords[2]}<input data-n-percent type="number" inputmode="decimal" min="0" max="100" step="any"></label></div><output data-n-output aria-live="polite">${calcWords[3]}</output><p class="hint">${calcWords[4]}</p>`;
 target.querySelector('.cn-meaning').after(calc);
 calc.oninput=()=>{const mass=calc.querySelector('[data-n-kg]').value,pct=calc.querySelector('[data-n-percent]').value,out=calc.querySelector('[data-n-output]');if(mass===''||pct===''){out.textContent=calcWords[3];return;}try{const n=nitrogenApplied(Number(mass),Number(pct));out.textContent=calcWords[5]+(n*1000).toLocaleString(language==='zh'?'zh-CN':language==='ms'?'ms-MY':'en',{maximumFractionDigits:2})+' g N / '+(language==='zh'?'棵 / 本次':language==='ms'?'pokok / penggunaan ini':'tree / application');}catch{out.textContent=calcWords[6];}};
 target.scrollIntoView({behavior:'smooth',block:'start'});
 }
 root.onclick=e=>{const next=e.target.closest('[data-next-stage]');if(next){const choice=durianNext(state)[Number(next.dataset.nextStage)];if(choice){Object.assign(state,choice.patch);saveDraft();render();result();}return;}if(e.target.closest('[data-resume-action]')){Object.assign(state,saved.answers);exampleMode=false;render();result();return;}const situation=e.target.closest('[data-situation]'),example=e.target.closest('[data-durian-example]');if(situation){exampleMode=false;state.situation=situation.dataset.situation;saveDraft();render();return;}if(example){exampleMode=true;Object.assign(state,{soil:'moist',health:'ok',bearing:'yes',nitrogen:'no',neighbours:'unknown',flush:'no'});const n=Number(example.dataset.durianExample);state.situation=n===1?'buds':'flush';if(n===0)state.nitrogen='yes';if(n===2)state.soil='wet';render();result();return;}if(e.target.closest('[data-save-action]')){const checked=[...root.querySelectorAll('[data-task]:checked')].map(el=>Number(el.dataset.task));saved={answers:{...state},key:decideDurian(state),checked,at:new Date().toISOString()};try{localStorage.setItem('cn-durian-action-v2',JSON.stringify(saved));root.querySelector('.durian-save-status').textContent=t.journalSaved;}catch{root.querySelector('.durian-save-status').textContent=language==='zh'?'浏览器未能保存，请保留截图。':language==='ms'?'Pelayar gagal menyimpan; simpan tangkap layar.':'The browser could not save; keep a screenshot.';} }};
 root.onchange=e=>{if(e.target.matches('[data-durian-answer]')){exampleMode=false;state[e.target.dataset.durianAnswer]=e.target.value;saveDraft();root.querySelector('.durian-result').replaceChildren();} };
 render();
}
